import {Button, TextInput, Flash, FormControl} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {XIcon} from '@primer/octicons-react'
import styles from './DeleteDialog.module.css'
import {useCallback, useState} from 'react'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useNavigate} from '@github-ui/use-navigate'

interface IDeleteDialogProps {
  setShowDeleteDialog: (showDialog: boolean) => void
  name: string
  id: string
  removeNetworkConfigurationPath: string
  networkConfigurationsPath?: string | null
  removeNetworkConfigurationFunction?: (networkId: string) => void | null
  enabledForCodespaces: boolean
}

export function DeleteDialog(props: IDeleteDialogProps) {
  const {
    id,
    name,
    enabledForCodespaces,
    removeNetworkConfigurationPath,
    removeNetworkConfigurationFunction,
    networkConfigurationsPath,
    setShowDeleteDialog,
  } = props
  const {addToast} = useToastContext()
  const navigate = useNavigate()
  const [isCorrectConfirmationDelete, setIsCorrectConfirmationDelete] = useState(false)
  const [submitClickedDelete, setSubmitClickedDelete] = useState(false)
  const onDeleteDialogClose = useCallback(() => {
    setIsCorrectConfirmationDelete(false)
    setSubmitClickedDelete(false)
    setShowDeleteDialog(false)
  }, [setShowDeleteDialog])
  const removeNetworkConfiguration = async () => {
    setSubmitClickedDelete(true)
    if (!isCorrectConfirmationDelete) return

    setShowDeleteDialog(false)
    try {
      const result = await verifiedFetchJSON(removeNetworkConfigurationPath, {
        method: 'DELETE',
        body: {configurationId: id},
      })
      if (result.ok) {
        if (removeNetworkConfigurationFunction) {
          removeNetworkConfigurationFunction(id)
        } else if (networkConfigurationsPath) {
          navigate(networkConfigurationsPath)
        }
        return
      }
    } catch {
      // fall through to error toast
    }
    // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
    addToast({
      type: 'error',
      message: 'There was an error deleting the network configuration',
    })
  }
  const showError = submitClickedDelete && !isCorrectConfirmationDelete

  return (
    <Dialog title="Delete network configuration" onClose={onDeleteDialogClose} width="large">
      <div className={styles.dialogContent}>
        <Flash variant="warning">
          Deleting a network configuration will remove it from your enterprise account and from all organizations that
          have access to this configuration.
        </Flash>
        <div className={styles.flexRow}>
          <XIcon size={16} className={styles.dangerIcon} />
          <span className={styles.textWithLeftPadding}>
            All associated <strong>workflows</strong> using this configuration will stop running.
          </span>
        </div>
        {enabledForCodespaces && (
          <div className={styles.flexRow}>
            <XIcon size={16} className={styles.dangerIcon} />
            <span className={styles.textWithLeftPadding}>
              <strong>Codespaces</strong> configured to use this configuration will no longer have access to internal
              resources granted to the given configuration.
            </span>
          </div>
        )}
        {enabledForCodespaces ? (
          <div>
            Before deleting, please consider updating the network settings for runner groups using this configuration as
            well as updating or removing any codespaces org policies that reference this configuration.
          </div>
        ) : (
          <div>
            Before deleting, please consider updating the network settings for runner groups using this configuration.
          </div>
        )}
        <FormControl required>
          <FormControl.Label style={{fontWeight: 'normal'}}>
            Please type <b>{name}</b> to confirm.
          </FormControl.Label>
          <TextInput
            block
            aria-label={`Please type ${name} to confirm`}
            name={`Please type ${name} to confirm`}
            onChange={e => setIsCorrectConfirmationDelete(e.target.value.trim() === name)}
            validationStatus={showError ? 'error' : undefined}
          />
          {showError && (
            <FormControl.Validation variant="error" aria-live="polite">
              Must match {name}
            </FormControl.Validation>
          )}
        </FormControl>
        <Button block variant="danger" onClick={removeNetworkConfiguration} className="ml-0">
          I understand, delete this network configuration
        </Button>
      </div>
    </Dialog>
  )
}
